var VAGUE_WORDS = ['fast', 'user-friendly', 'easy', 'flexible', 'efficient', 'robust', 'appropriate', 'adequate', 'several', 'etc', 'and/or', 'support'];

function lint(text) {
  var t = String(text);
  var issues = [];
  var shall = (t.match(/\bshall\b/gi) || []).length;
  if (shall === 0) issues.push('NO_SHALL');
  if (shall > 1) issues.push('MULTI');
  var low = t.toLowerCase();
  var vague = VAGUE_WORDS.some(function (w) {
    var esc = w.replace(/[.*+?^${}()|[\]\\\/-]/g, '\\$&');
    return new RegExp('(^|[^a-z0-9-])' + esc + '(?![a-z0-9-])').test(low);
  });
  if (vague) issues.push('VAGUE');
  if (/\bshall be \w+(ed|en)\b/i.test(t)) issues.push('PASSIVE');
  if (/TBD/.test(t)) issues.push('TBD');
  return issues;
}
